<?php
namespace App\Http\Controllers;
use App\Http\Requests\CustomerRequest; use App\Models\Customer; use Illuminate\Http\Request;
class CustomerController extends Controller { public function index(Request $request){$customers=Customer::query()->when($request->search,fn($q,$s)=>$q->where(fn($q)=>$q->where('name','like',"%$s%")->orWhere('email','like',"%$s%")))->latest()->paginate(15)->withQueryString();return view('resources.index',compact('customers'))->with('resource','customers');} public function create(){return view('resources.form',['resource'=>'customers','record'=>new Customer]);} public function store(CustomerRequest $request){Customer::create($request->validated());return redirect()->route('customers.index')->with('success','Customer created.');} public function edit(Customer $customer){return view('resources.form',['resource'=>'customers','record'=>$customer]);} public function update(CustomerRequest $request,Customer $customer){$customer->update($request->validated());return redirect()->route('customers.index')->with('success','Customer updated.');} public function destroy(Customer $customer){$customer->delete();return back()->with('success','Customer deleted.');} }
